    { title: '本周体验课优先分配', leads: 'Sarah / Mike / Eva', action: '去分配', color: 'border-l-black' },
    { title: '需控课老师 (高负载)', leads: '赵D (98%) / Sarah (90%)', action: '去调整', color: 'border-l-orange-500' },
    { title: '新老师培养建议', leads: '陈E (成交回升)', action: '去沟通', color: 'border-l-blue-500' },
    { title: '业绩风险预警', leads: 'David (转化持续下滑)', action: '去面谈', color: 'border-l-red-500' }
  ];

  // --- Logic 2: Matrix Data ---
  const matrixData = useMemo(() => {
    return MOCK_STAFF_LIST.filter(s => s.type === 'teacher').map(s => ({
      x: s.conversionRate,
      y: s.loadFactor,
      name: s.name,
      id: s.id,
      level: s.level
    }));
  }, []);

  // --- Logic 3: Rankings ---
  const teachers = MOCK_STAFF_LIST.filter(s => s.type === 'teacher');
  const consumptionTop = [...MOCK_STAFF_LIST].sort((a, b) => b.classHours - a.classHours).slice(0, 5);
  const conversionTop = [...teachers].sort((a, b) => b.conversionRate - a.conversionRate).slice(0, 5);
  const conversionBottom = [...teachers].sort((a, b) => a.conversionRate - b.conversionRate).slice(0, 3);
  // New: Occupancy Ranking
  const occupancyTop = [...teachers].sort((a, b) => b.occupancyRate - a.occupancyRate).slice(0, 5);

  // --- Logic 4: Filtered Staff List ---
  const filteredStaff = useMemo(() => {
    let list = MOCK_STAFF_LIST;

    // Tab Filters
    if (filterType === 'leads') list = list.filter(s => s.conversionRate > 60 && s.loadFactor < 80);
    if (filterType === 'adjust') list = list.filter(s => s.loadFactor > 90 || s.conversionRate < 30);
    if (filterType === 'new') list = list.filter(s => s.expYears.includes('0') || s.expYears.includes('1'));

    // Search Filter
    if (searchQuery) {
        const q = searchQuery.toLowerCase();
        list = list.filter(s => 
            s.name.toLowerCase().includes(q) || 
            s.tags.some(t => t.toLowerCase().includes(q)) ||
            s.title.toLowerCase().includes(q)
        );
    }

    return list;
  }, [filterType, searchQuery]);

  const getAiSuggestion = (s: Staff) => {
    if (s.conversionRate > 75 && s.loadFactor < 70) return { text: '适合接体验', color: 'text-green-600', bg: 'bg-green-50' };
    if (s.loadFactor > 90) return { text: '建议控课', color: 'text-orange-600', bg: 'bg-orange-50' };
    if (s.conversionRate < 30) return { text: '需要培养', color: 'text-blue-600', bg: 'bg-blue-50' };
    return { text: '状态稳定', color: 'text-gray-500', bg: 'bg-gray-100' };
