interface CardItem {
    id: string;
    name: string;
    cover?: string; // New: Image
    slogan: string;
    guideText: string;
    category: 'stored' | 'term';
    type: string; 
    price: number;

    // Stored Value Specifics
    points?: number;
    initialIntegration?: number;
    maxGiftIntegration?: number;
    exchangeRatio?: number;

    // Common & Structured Rules
    validity: number; 
    bookingRange: number; 
    minStart: number; 
    cancelLimit: number; 
    noShowPenalty: 'deduct' | 'freeze';
    leaveMin: number; 
    leaveMax: number; 
    checkInBonus: number; 

    // Scope
    courseScope: string[]; // New: Array of selected course types
    venueScope: 'all' | 'specific';

    // Data Fields
    sales30d: number;
    totalSales: number;
    renewalRate: number; 
    avgConsumptionCycle: number; 
    status: 'active' | 'inactive';
}

// 2. TTC (Research Center)
interface TTCSchedule {
    id: string;
    batchName: string; 
    startDate: string;
    endDate: string;
    enrolled: number;
    max: number;
    status: 'recruiting' | 'full' | 'ended';
}

interface TTCCourse {
    id: string;
    name: string;
    category: 'yoga' | 'pilates';
    cover: string;
    price: number;
    earlyBirdPrice: number;
    earlyBirdDeadline: string; 
    alumniPrice: number;
    intro: string;
    plan: string;
    targetAudience: string[]; // New: Tags array
    outcomes: string;
    tutors: string[];
    schedules: TTCSchedule[];
    status: 'active' | 'inactive';
    // Data
    conversionRate: number;
    views: number;
    historicalSales: number[]; 
}

interface Student {
    id: string;
    name: string;
    phone: string;
    paymentStatus: 'paid' | 'deposit' | 'pending' | 'refunded';
    amount: number;
    confirmed: boolean;
    batch: string;
    signupDate: string;
}

// 3. Points Mall (Enhanced)
interface PointProduct {
    id: string;
    name: string;
    type: 'physical' | 'course'; 
    cover: string;

    // Exchange Rules (New)
    allowPointsOnly: boolean;
    pointsPrice: number;
    allowMixed: boolean;
    mixedPoints: number;
    mixedCash: number;

    // Attributes
    colors?: string[]; // New
    sizes?: string[]; // New

    stock: number; 
    warningStock: number;
    validity?: string; 

    // Scope
    venueScope: 'all' | 'specific'; // New

    status: 'active' | 'inactive';
    // Data
    exchangedCount: number;
    inventoryRate: number; 
    recentLog: {user: string, time: string}[];
}

// 4. Orders
interface Order {
    id: string;
    user: string;
    product: string;
    category: 'card' | 'ttc' | 'mall';
    amount: string;
    status: 'paid' | 'pending' | 'refunded' | 'completed';
    time: string;
}

