import React, { useState } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Cell
} from 'recharts';

// --- Constants ---
const AVAILABLE_VENUES = ['万象城馆', '西湖旗舰馆', '滨江宝龙馆', '城西银泰馆'];

// --- Types ---

// 1. Cards
interface CardItem {
    id: string;
    name: string;
    cover?: string;
    slogan: string;
    guideText: string;
    category: 'stored' | 'term';
    type: string; 
    price: number;
    points?: number;
    initialIntegration?: number;
    maxGiftIntegration?: number;
    exchangeRatio?: number;
    validity: number; 
    bookingRange: number; 
    minStart: number; 
    cancelLimit: number; 
    noShowPenalty: 'deduct' | 'freeze';
    noShowPenaltyValue: number;
    leaveMin: number; 
    leaveMax: number; 
    checkInBonus: number; 
    courseScope: string[];
    venueScope: 'all' | 'specific'; 
    listingVenues: string[];
    sales30d: number;
    totalSales: number;
    renewalRate: number; 
    avgConsumptionCycle: number; 
    status: 'active' | 'inactive';
}

// 2. TTC (Research Center)
interface TTCSchedule {
    id: string;
    batchName: string; 
    startDate: string;
    endDate: string;
    enrolled: number;
    max: number;
    status: 'recruiting' | 'full' | 'ended';
