import React, { useState } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Cell
} from 'recharts';

// --- Constants ---
const AVAILABLE_VENUES = ['万象城馆', '西湖旗舰馆', '滨江宝龙馆', '城西银泰馆'];

// --- Types ---

// 1. Cards
interface CardItem {
    id: string;
    name: string;
    cover?: string;
    slogan: string;
    guideText: string;
    category: 'stored' | 'term';
    type: string; 
    price: number;
    points?: number;
    initialIntegration?: number;
    maxGiftIntegration?: number;
    exchangeRatio?: number;
    validity: number; 
    bookingRange: number; 
    minStart: number; 
    cancelLimit: number; 
    noShowPenalty: 'deduct' | 'freeze';
    noShowPenaltyValue: number;
    leaveMin: number; 
    leaveMax: number; 
    checkInBonus: number; 
    courseScope: string[];
    venueScope: 'all' | 'specific'; 
    listingVenues: string[];
    sales30d: number;
    totalSales: number;
    renewalRate: number; 
    avgConsumptionCycle: number; 
    status: 'active' | 'inactive';
}

// 2. TTC (Research Center)
interface TTCSchedule {
    id: string;
    batchName: string; 
    startDate: string;
    endDate: string;
    enrolled: number;
    max: number;
    status: 'recruiting' | 'full' | 'ended';
}

// New: Tutor Interface with Structured Resume
interface TTCTutorExperience {
    year: string;
    title: string;
}

interface TTCTutor {
    id: string;
    name: string;
    title: string; // e.g. E-RYT 500
    avatar: string;
    motto: string; // 名言
    resume: TTCTutorExperience[]; // Structured Resume
    gallery: string[]; // 授课瞬间
    status: 'active' | 'inactive';
}

// New: Course Interface with Structured Plan & Audience
interface TTCCoursePlanNode {
    stage: string;
    content: string;
}

interface TTCCourseAudienceNode {
    tag: string; // 概括性词语 e.g. "零基础人群"
    desc: string; // 解释性词语 e.g. "建立正确且安全的练习根基"
}

interface TTCCourse {
    id: string;
    name: string;
    category: 'yoga' | 'pilates';
    cover: string;
    price: number;
    earlyBirdPrice: number;
    earlyBirdDeadline: string; 
    alumniPrice: number;
    intro: string;

    // New Structured Fields
    planNodes: TTCCoursePlanNode[]; 
    audienceNodes: TTCCourseAudienceNode[];

    outcomes: string;
    tutors: string[]; // Array of Tutor IDs or Names
    schedules: TTCSchedule[];
    listingVenues: string[];
    status: 'active' | 'inactive';
    conversionRate: number;
    views: number;
    historicalSales: number[]; 
}

interface Student {
    id: string;
    name: string;
    phone: string;
    paymentStatus: 'paid' | 'deposit' | 'pending' | 'refunded';
    amount: number;
    confirmed: boolean;
    batch: string;
    signupDate: string;
}

// 3. Points Mall
interface ProductSpecValue {
    name: string;
    image?: string; 
}

